"""Reviewed, self-contained adaptations; no automatic PDF answer-key inference."""
import json,hashlib
from pathlib import Path
rows=[]
def add(course,source,page,locator,prompt,correct,wrong,hint,explanation):
 rows.append(dict(course=course,sourceIndex=source,page=page,locator=locator,prompt=prompt,correct=correct,wrong=wrong,hint=hint,explanation=explanation))
def c(source,page,locator,prompt,correct,wrong,hint,explanation):add('chinese',source,page,locator,prompt,correct,wrong,hint,explanation)
