# The two read-only subject reviewers supply candidates; root curates and writes their accepted data here.
for name in ['science','english']:
 p=Path(f'scripts/imports/jay-grade5-{name}-curated.json')
 if p.exists():
  for q in json.loads(p.read_text()):
   add(name,q['sourceIndex'],q['page'],q['locator'],q['prompt'],q['options'][q['answer']],[s for i,s in enumerate(q['options']) if i!=q['answer']],q['hint'],q['explanation'])
Path('scripts/imports/jay-grade5-curated.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n')
result=[];ids=set()
for r in rows:
 key=f"{r['course']}:{r['sourceIndex']}:{r['page']}:{r['locator']}";qid='j5-'+hashlib.sha256(key.encode()).hexdigest()[:18];assert qid not in ids;ids.add(qid)
 choices=[r['correct'],*r['wrong']];assert len(choices)==len(set(choices));shift=int(hashlib.sha256(key.encode()).hexdigest()[-4:],16)%len(choices);choices=choices[shift:]+choices[:shift]
 result.append(dict(id=qid,grade=5,course=r['course'],subject=r['course'],publisher='翰林',level=2,prompt=r['prompt'],options=[{'text':s} for s in choices],answer=choices.index(r['correct']),hint=r['hint'],explanation=r['explanation'],examSources=[dict(id=f"j5s{r['sourceIndex']}",page=r['page'],locator=r['locator'],kind='歷屆筆試改編；必要情境已補齊')]))
Path('src/grade5-dongmen-exams.ts').write_text("import type {LearningQuestion} from './learning';\nexport const GRADE5_DONGMEN_EXAMS: LearningQuestion[] = "+json.dumps(result,ensure_ascii=False,indent=2)+';\n')
print({course:sum(q['course']==course for q in result) for course in ['chinese','science','english']})
